<template>
  <main class="page action-overview">
    <header class="action-overview__head">
      <div><p>ACTION OVERVIEW</p><h1>{{ greeting }}，{{ auth.displayName || viewRoleName }}</h1></div>
      <div class="head-actions"><button class="refresh" type="button" aria-label="刷新工作台" @click="load"><van-icon name="replay" /></button></div>
    </header>

    <template v-if="workspace === 'overview'">
    <section v-if="primaryTask" class="today-focus" :class="`today-focus--${primaryTask.severity}`">
      <div class="today-focus__head"><span>今日焦点</span><small>{{ primaryTask.status }}</small></div>
      <h2>{{ primaryTask.title }}</h2><p>{{ primaryTask.meta }}</p>
      <button type="button" @click="open(primaryTask)">{{ primaryTask.action_label || '去处理' }}<van-icon name="arrow" /></button>
    </section>
    <section v-else class="clear-state"><van-icon name="passed" /><div><b>当前没有紧急事项</b><span>新的工作会自动排进清单</span></div></section>

    <section class="business-workspace">
      <h2 class="section-label">业务工作台</h2>
      <div class="business-workspace__grid"><button v-for="item in businessAreas" :key="item.role" type="button" :class="`business-area business-area--${item.tone}`" @click="openWorkspace(item.role)"><span><van-icon :name="item.icon" /></span><b>{{ item.label }}</b></button></div>
    </section>

    <section class="today-metrics">
      <h2 class="section-label">今日指标</h2>
      <div class="today-metrics__grid"><div><van-icon name="logistics" class="blue" /><span>待入库</span><b>{{ data.counts?.purchase_receive || 0 }}<small>项</small></b></div><div><van-icon name="chart-trending-o" class="green" /><span>直通率</span><b>{{ passRate }}<small>%</small></b></div><div><van-icon name="warning-o" class="orange" /><span>待判定</span><b>{{ data.counts?.iqc || 0 }}<small>项</small></b></div></div>
    </section>

    <section v-if="displayTasks.length" class="agenda">
      <div class="section-title"><h2>行动清单</h2><span>{{ actionCount }} 项待办</span></div>
      <div class="agenda__list"><button v-for="task in displayTasks" :key="taskKey(task)" class="agenda-card" type="button" @click="open(task)">
        <div class="agenda-card__top"><em :class="`agenda-card__tag agenda-card__tag--${task.severity}`">{{ task.status }}</em><span>{{ task.source }}</span></div>
        <h3>{{ task.title }}</h3><p>{{ task.meta }}</p>
        <div class="agenda-card__action"><b>{{ task.action_label || '去处理' }}</b><van-icon name="arrow" /></div>
      </button></div>
      <button v-if="actionCount > 3" class="all-actions" type="button" @click="showAll = !showAll">{{ showAll ? '收起' : `查看全部 ${actionCount} 项` }}<van-icon :name="showAll ? 'arrow-up' : 'arrow-down'" /></button>
    </section>
    </template>

    <template v-else-if="workspace === 'manager'">
      <header class="role-pane__head"><button type="button" @click="workspace = 'overview'"><van-icon name="arrow-left" /></button><div><p>MANAGEMENT INSIGHT</p><h1>经营全貌</h1></div></header>
      <section class="management-kpis"><article><span>交付风险</span><b class="red">{{ board.summary?.at_risk_orders || 0 }}<small>异常</small></b></article><article><span>产能瓶颈</span><b class="orange">{{ board.summary?.rush_orders || 0 }}<small>单关注</small></b></article><article><span>缺料预警</span><b class="blue">{{ shortages }}<small>项</small></b></article><article><span>待结算额</span><b class="green">¥{{ money(kpi.customer_ar_balance) }}</b></article></section>
      <h2 class="role-pane__label">资金与结算</h2><section class="settlement-card"><span>本月已收回款</span><b>¥{{ money(kpi.payment_amount) }}</b><div><span>员工薪资结算<em>¥{{ money(kpi.salary_amount) }}</em></span><span>供应商货款<em>¥{{ money(kpi.supplier_ap_balance) }}</em></span></div></section>
    </template>

    <template v-else-if="workspace === 'warehouse'">
      <header class="role-pane__head"><button type="button" @click="workspace = 'overview'"><van-icon name="arrow-left" /></button><div><p>MATERIAL WORKSPACE</p><h1>物料工作台</h1></div><button type="button" @click="load"><van-icon name="replay" /></button></header>
      <div class="material-steps"><b>缺料</b><b>采购</b><span>在途</span><span>到货</span><span>入库</span></div>
      <h2 class="role-pane__label">待办中心</h2><section class="material-urgent"><div><strong><i></i>紧迫缺料（{{ shortages }}）</strong><span>影响齐套与交期</span></div><h3>待买物料与来料跟进</h3><p>当前有 {{ shortages }} 项物料影响生产齐套</p><button type="button" @click="router.push('/orders')">去跟进</button></section>
      <h2 class="role-pane__label">物料看板</h2><section class="two-metrics"><div><span>预计今日到达</span><b>{{ data.counts?.purchase_receive || 0 }}<small>单</small></b></div><div><span>待 IQC 判定</span><b>{{ data.counts?.iqc || 0 }}<small>项</small></b></div></section>
    </template>

    <template v-else-if="workspace === 'workshop'">
      <header class="role-pane__head"><button type="button" @click="workspace = 'overview'"><van-icon name="arrow-left" /></button><div><p>ON-SITE PRODUCTION</p><h1>生产现场管理</h1></div><button type="button" @click="load"><van-icon name="replay" /></button></header>
      <section class="site-alert"><span>现场异常</span><h2>{{ primaryTask?.title || '今日现场运行正常' }}</h2><p>{{ primaryTask?.meta || '持续关注报工、不良与班组现场情况' }}</p><div><button type="button" @click="router.push('/work-logs')">查看报工</button><button type="button" @click="router.push('/orders')">查看排产</button></div></section>
      <h2 class="role-pane__label">今日班次概况</h2><section class="two-metrics"><div><span>今日产量</span><b>{{ today.total_qualified || 0 }}<small>件</small></b></div><div><span>平均工时</span><b>—<small>h</small></b></div></section>
    </template>

    <template v-else-if="workspace === 'finance'">
      <header class="role-pane__head"><button type="button" @click="workspace = 'overview'"><van-icon name="arrow-left" /></button><div><p>FINANCIAL SETTLEMENT</p><h1>资金结算工作台</h1></div></header>
      <section class="finance-close"><span>本月待关账</span><div><p>应收待结</p><b>¥{{ money(kpi.customer_ar_balance) }}</b><p>应付待结</p><b>¥{{ money(kpi.supplier_ap_balance) }}</b></div><button type="button">立即结算关账</button></section>
      <h2 class="role-pane__label">资金看板</h2><section class="three-metrics"><div><span>本月收款</span><b>¥{{ money(kpi.payment_amount) }}</b></div><div><span>本月支出</span><b>¥{{ money(kpi.expense_amount) }}</b></div><div><span>净利润预测</span><b>—</b></div></section>
    </template>

    <van-dialog v-model:show="customerShow" title="登记客供到货" show-cancel-button @confirm="receiveCustomer"><van-cell title="本次到货"><template #value><van-field v-model="qty" type="number" inputmode="decimal" placeholder="填写数量" /></template></van-cell><van-field v-model="note" label="备注" placeholder="可选" /></van-dialog>
    <van-action-sheet v-model:show="iqcShow" :actions="iqcActions" cancel-text="取消" @select="decideIqc" />
    <van-action-sheet v-model:show="roleSheetShow" :actions="roleActions" cancel-text="取消" @select="switchRole" />
  </main>
</template>

<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { showToast } from 'vant'
import http from '@/api/http'
import { useAuthStore } from '@/stores/auth'

const router = useRouter(); const auth = useAuthStore()
const data = ref<any>({ roles: [], counts: {}, tasks: [] }); const board = ref<any>({ summary: {} }); const today = ref<any>({}); const shortages = ref(0); const kpi = ref<any>({})
const selected = ref<any>(null); const customerShow = ref(false); const iqcShow = ref(false); const qty = ref(''); const note = ref(''); const showAll = ref(false)
const roleSheetShow = ref(false); const activeRole = ref('')
const workspace = ref('overview')
const iqcActions = [{ name: '合格入库', value: 'pass', color: '#07a56c' }, { name: '让步接收', value: 'concede', color: '#e79c13' }, { name: '不合格处置', value: 'fail', color: '#e24b4b' }]
const severityOrder: Record<string, number> = { overdue: 0, due_soon: 1, warning: 2, info: 3 }
const money = (value: unknown) => Number(value || 0).toLocaleString('zh-CN', { maximumFractionDigits: 0 })
const roleCodes = computed(() => data.value.roles.map((item: any) => item.code).filter(Boolean))
const viewRole = computed(() => activeRole.value || roleCodes.value[0] || auth.role)
const roleNameMap: Record<string, string> = { admin: '管理员', manager: '厂长', merchandiser: '跟单', warehouse: '采购仓管', finance: '财务', workshop: '车间主管' }
const viewRoleName = computed(() => roleNameMap[viewRole.value] || '工作台')
const roleActions = computed(() => roleCodes.value.map((code: string) => ({ name: roleNameMap[code] || code, value: code })))
const isManagement = computed(() => viewRole.value === 'manager' || viewRole.value === 'admin'); const isMerchandiser = computed(() => viewRole.value === 'merchandiser'); const isWarehouse = computed(() => viewRole.value === 'warehouse'); const isFinance = computed(() => viewRole.value === 'finance'); const isWorkshop = computed(() => viewRole.value === 'workshop')
const greeting = computed(() => { const h = new Date().getHours(); return h < 11 ? '早上好' : h < 18 ? '下午好' : '晚上好' })
const roleTasks = computed(() => {
  const tasks = data.value.tasks || []
  if (isManagement.value) return tasks
  if (isWarehouse.value) return tasks.filter((task: any) => ['采购', '客供', 'IQC'].includes(task.source))
  if (isMerchandiser.value) return tasks.filter((task: any) => task.source === '客供')
  return []
})
const rankedTasks = computed(() => [...roleTasks.value].sort((a, b) => (severityOrder[a.severity] ?? 9) - (severityOrder[b.severity] ?? 9)))
const primaryTask = computed(() => rankedTasks.value[0]); const actionCount = computed(() => rankedTasks.value.length)
const agendaTasks = computed(() => showAll.value ? rankedTasks.value.slice(1) : rankedTasks.value.slice(1, 4))
const displayTasks = computed(() => showAll.value ? rankedTasks.value : rankedTasks.value.slice(0, 3))
const passRate = computed(() => { const total = Number(today.value.total_qualified || 0) + Number(today.value.total_defect || 0); return total ? (Number(today.value.total_qualified || 0) / total * 100).toFixed(1) : '—' })
const businessAreas = [
  { role: 'manager', label: '经营', icon: 'chart-trending-o', tone: 'orange' },
  { role: 'merchandiser', label: '交付', icon: 'orders-o', tone: 'blue' },
  { role: 'warehouse', label: '物料', icon: 'bag-o', tone: 'green' },
  { role: 'workshop', label: '现场', icon: 'cluster-o', tone: 'purple' },
  { role: 'finance', label: '财务', icon: 'balance-o', tone: 'red' },
]
const focusCards = computed(() => {
  if (isFinance.value && !isManagement.value) return [{ label: '本月回款', value: `¥${money(kpi.value.payment_amount)}`, note: '已到账', icon: 'balance-o', tone: 'blue' }, { label: '待收款', value: `¥${money(kpi.value.customer_ar_balance)}`, note: '需跟进', icon: 'warning-o', tone: 'warning' }]
  if (isWarehouse.value && !isManagement.value) return [{ label: '待到货', value: `${data.value.counts?.purchase_receive || 0} 项`, note: '采购来料', icon: 'logistics', tone: 'blue' }, { label: '待 IQC', value: `${data.value.counts?.iqc || 0} 项`, note: '等待判定', icon: 'certificate', tone: 'warning' }, { label: '未到预警', value: `${Number(data.value.counts?.overdue || 0) + Number(data.value.counts?.due_today || 0)} 项`, note: '优先跟进', icon: 'warning-o', tone: 'danger' }]
  if (isMerchandiser.value && !isManagement.value) return [{ label: '交期风险', value: `${board.value.summary?.at_risk_orders || 0} 单`, note: '需跟进', icon: 'orders-o', tone: 'danger', to: '/orders' }, { label: '待买缺料', value: `${shortages.value} 项`, note: '影响齐套', icon: 'bag-o', tone: 'warning', to: '/orders' }]
  if (isWorkshop.value) return [{ label: '今日生产', value: `${today.value.total_qualified || 0}`, note: `不良 ${today.value.total_defect || 0}`, icon: 'chart-trending-o', tone: 'ok', to: '/work-logs' }, { label: '交期风险', value: `${board.value.summary?.at_risk_orders || 0} 单`, note: '关注排产', icon: 'orders-o', tone: 'danger', to: '/orders' }]
  return [{ label: '今日生产', value: `${today.value.total_qualified || 0}`, note: `不良 ${today.value.total_defect || 0}`, icon: 'chart-trending-o', tone: 'ok', to: '/work-logs' }, { label: '交期风险', value: `${board.value.summary?.at_risk_orders || 0} 单`, note: '需关注', icon: 'orders-o', tone: 'danger', to: '/orders' }, { label: '来料预警', value: `${Number(data.value.counts?.overdue || 0) + Number(data.value.counts?.due_today || 0)} 项`, note: '待处理', icon: 'logistics', tone: 'warning' }]
})
const roleShortcuts = computed(() => {
  if (isWarehouse.value) return [{ label: '采购到货', note: '登记与检验', icon: 'logistics', to: '/workbench' }, { label: '来料 IQC', note: '判定入库', icon: 'certificate', to: '/workbench' }]
  if (isWorkshop.value) return [{ label: '排产派工', note: '订单工序', icon: 'orders-o', to: '/orders' }, { label: '报工纠错', note: '作废或更正', icon: 'notes-o', to: '/work-logs' }]
  if (isMerchandiser.value) return [{ label: '订单进度', note: '交付与齐料', icon: 'orders-o', to: '/orders' }, { label: '客户供料', note: '到货跟进', icon: 'logistics', to: '/workbench' }]
  return []
})
function taskKey(task: any) { return `${task.kind}-${task.id || task.to || task.title}` }
function switchRole(action: any) { activeRole.value = String(action.value || ''); showAll.value = false }
function selectWorkspace(role: string) { activeRole.value = role; showAll.value = false; window.scrollTo({ top: 0, behavior: 'smooth' }) }
function openWorkspace(role: string) { if (role === 'merchandiser') { router.push('/orders'); return }; workspace.value = role; selectWorkspace(role) }
function open(task: any) { selected.value = task; if (task.to) router.push(task.to); else if (task.kind === 'customer_receive') customerShow.value = true; else if (task.kind === 'iqc') iqcShow.value = true }
async function receiveCustomer() { if (!qty.value || Number(qty.value) <= 0) return showToast('请填写本次到货数量'); await http.post(`/customer-supply/${selected.value.id}/receive`, { qty: Number(qty.value), note: note.value || undefined }); qty.value = ''; note.value = ''; await load(); showToast('已登记到货') }
async function decideIqc(action: any) { await http.post(`/material-iqc/${selected.value.id}/decide`, { decision: action.value }); await load(); showToast('已完成判定') }
async function load() { try { const overview: any = await http.get('/mobile-workbench/overview'); data.value = overview.data || data.value; if (!activeRole.value && roleCodes.value.length) activeRole.value = auth.role && roleCodes.value.includes(auth.role) ? auth.role : roleCodes.value[0]; const requests: any[] = [http.get('/progress/today').catch(() => ({ data: {} })), http.get('/progress/board').catch(() => ({ data: { summary: {} } })), http.get('/sales-orders/demand-shortages', { params: { include_shared: true } }).catch(() => ({ data: {} }))]; if (roleCodes.value.includes('finance')) requests.push(http.get('/business-kpi').catch(() => ({ data: {} }))); const result: any[] = await Promise.all(requests); today.value = result[0].data || {}; board.value = result[1].data || { summary: {} }; shortages.value = Number(result[2].data?.to_buy_lines || 0); kpi.value = result[3]?.data || {} } catch { showToast('加载工作台失败') } }
watch(roleCodes, (codes) => { if (activeRole.value && !codes.includes(activeRole.value)) activeRole.value = codes[0] || '' })
onMounted(load)
</script>

<style scoped>
